函数的一般形式12345fun mathodName(/*para list*/) : String/*return value type*/ { /* function body */} 与C、C++或java的不同 如果要重载，在fun前面加override 如果想让子类重载，要加open关键词（类也一样） 可以定义全局函数，函数不是必须写在类里 可以有默认参数，且默认参数不必放在最后几个123456789101112fun TextView.println(str:CharSequence) { append(&quot;
${str}&quot;)}fun TextView.print(str:CharSequence) { append(str)}//这个东西是扩展函数，后面说fun func(str:String = &quot;哈哈哈&quot;,i:Int, j:Double) {//str的默认参数&quot;哈哈哈&quot; val text:TextView = findViewById(R.id.text) text.print(&quot;$str&quot;) text.println(&quot;$i&quot;) text.println(&quot;$j&quot;)} 此时，在调用时，如果第一个不采用默认参数，则按照顺序传递三个参数，否则按照以下形式传递参数1func(i = 10, j = 20.5) 可变参数，在参数列表中，参数名称前用vararg（var = varable, arg = 参数）修饰1234567fun appendString(tag:String, vararg info:String?) : String { var str:String = &quot;${tag}&quot; for (item in info) { str = &quot;${str}
${item}&quot; } return str} Kotlin的特殊函数泛型函数/内联函数例子1234567fun&lt;T&gt; appendString(tag:String, vararg info:T?) : String { var str:String = &quot;${tag}&quot; for (item in info) { str = &quot;${str}
${item.toString()}&quot; } return str} 在fun后面加入&lt;泛型列表&gt;,表示泛型函数 调用方法123btn.setOnClickListener { text.text = appendString&lt;Int&gt;(&quot;转化&quot;, 1,2,3,4,5,6,7,8,9)} 注意 只有泛型类才拥有成员泛型函数，或者可以把泛型函数作为全局函数 Kotlin是强类型的语言，如果需要即传递Number类继承的类对象，而不继承其他类对象，不能写&lt;Number&gt; 要写成&lt;reified T : Number&gt;,这个写法等价于java的&lt;T extends Number&gt; 简化函数Kotlin中，函数的定义形式和变量十分相似，这是因为函数也是一种特殊变量，可以对他赋值 例子1fun factorial(n:Int):Int = if(n &lt;= 1) n else n*factorial(n-1) 尾递归函数在fun之前加上关键字tailrec(tail——尾巴，rec——不知道)，告诉编译器这是一个尾递归函数，编译器可以自动优化成循环 例子12tailrec fun findFixPoint(x:Double = 1.0) : Double = if (x == Math.cos(x)) x else findFixPoint(Math.cos(x)) 高阶函数传入的参数是一个函数，个人认为相当于C/C++的函数指针，或者说传递了一个函数变量 例子1234567891011121314fun&lt;T&gt; maxCustom(array:Array&lt;T&gt;, greater:(T,T) -&gt; Boolean) : T? { /* 这个地方 greater(T, T) -&gt; Boolean 表示一个函数名为greater，参数为两个T类型，返回值的Boolean的函数 */ var max:T? = null for (item in array) { if (max == null || greater(item, max)) { max = item } } return max} 调用1234val arr:Array&lt;Int&gt; = arrayOf(1,2,3)btn.setOnClickListener { text.text = &quot;最大值为${maxCustom&lt;Int&gt;(arr, {a,b -&gt; a &gt; b}).toString()}&quot;}//使用lambad表达式 系统增强函数扩展函数可以给已有的类中添加函数，作为成员函数 例子123456fun TextView.println(str:CharSequence) { append(&quot;${str}
&quot;)}fun TextView.print(str:CharSequence) { append(str)} 调用和正常成员函数一样调用 123456val text:TextView = findViewById(R.id.text)val btn:Button = findViewById(R.id.btn)btn.setOnClickListener { text.println(&quot;123&quot;) text.print(&quot;demo&quot;)} 单例对象用object替换class，这样其中的所有函数都是静态成员函数了 相当于static修饰符

[Hard] 715. Range 模块思路 二分查找 一开始想的是用[left, right)和全部区间进行比较查找，但是这样比较困难，在处理边界合并情况时会变成O(N) 用left和right分别在所有ranges中查找 对于query，如果两个下标相同，则true，否则false 对于add，查找left-1和right的下标，然后其间的所有ranges删除，插入新range 对于remove，查找left和right-1的下标，然后根据下标把之间的删除，插入剩余的区间 ac代码 RangeModule { vector&lt;pair&lt;int, int&gt;&gt; ranges; int len = 0; int ops = 0; static constexpr bool debug = false; void printRanges() { int size = ranges.size(); cout &lt;&lt; &quot;len = &quot; &lt;&lt; len &lt;&lt; &quot;, size = &quot; &lt;&lt; size &lt;&lt; &quot;
&quot;; for(int i = 0; i &lt; size; i++) { cout &lt;&lt; &quot;[&quot; &lt;&lt; ranges[i].first &lt;&lt; &quot;, &quot; &lt;&lt; ranges[i].second &lt;&lt; &quot;]
&quot;; } } bool inRange(int n, int index) { return ranges[index].first &lt;= n &amp;&amp; n &lt; ranges[index].second; } bool bigger(int n, int index) { return n &gt;= ranges[index].second; } bool smaller(int n, int index) { return ranges[index].first &gt; n; } int searchRanges(int n) { int l = 0, r = len; while(l &lt; r) { int mid = (r - l) / 2 + l; if(inRange(n, mid)) return mid; else if(bigger(n, mid)) { l = mid + 1; } else { r = mid; } } return l; }public: RangeModule() { } void addRange(int left, int right) { // if(debug) { // ops++; // cout &lt;&lt; &quot;[&quot; &lt;&lt; ops &lt;&lt; &quot;], &quot; &lt;&lt; &quot;addRange&quot; &lt;&lt; &quot;[&quot; &lt;&lt; left &lt;&lt; &quot;, &quot; &lt;&lt; right &lt;&lt; &quot;]&quot; &lt;&lt; &quot;
&quot;; // } _addRange(left, right); // if(debug) printRanges(); } void _addRange(int left, int right) { int leftIndex = searchRanges(left-1); int rightIndex = searchRanges(right); // add时考虑合并相邻的集合，所以把边界放宽 // if(leftIndex &gt; 0 &amp;&amp; ranges[leftIndex - 1].second == left) { // leftIndex--; // } // if(rightIndex &lt; len - 1 &amp;&amp; ranges[rightIndex + 1].first == ) // if(debug) cout &lt;&lt; &quot;leftIndex = &quot; &lt;&lt; leftIndex &lt;&lt; &quot;, rightIndex = &quot; &lt;&lt; rightIndex &lt;&lt; &quot;
&quot;; if(leftIndex == rightIndex &amp;&amp; leftIndex == len) { } else { left = min(left, ranges[leftIndex].first); if(rightIndex &lt; len) { if(inRange(right, rightIndex)) { right = max(right, ranges[rightIndex].second); rightIndex++; } } ranges.erase(ranges.begin() + leftIndex, ranges.begin() + rightIndex); len -= rightIndex - leftIndex; } ranges.insert(ranges.begin() + leftIndex, make_pair(left, right)); len++; } bool queryRange(int left, int right) { // if(debug) { // ops++; // cout &lt;&lt; &quot;[&quot; &lt;&lt; ops &lt;&lt; &quot;], &quot; &lt;&lt; &quot;queryRange&quot; &lt;&lt; &quot;[&quot; &lt;&lt; left &lt;&lt; &quot;, &quot; &lt;&lt; right &lt;&lt; &quot;]&quot; &lt;&lt; &quot;
&quot;; // } bool ret = _queryRange(left, right); // if(debug) cout &lt;&lt; (ret ? &quot;ok&quot; : &quot;not found&quot;) &lt;&lt; &quot;
&quot;; // if(debug) printRanges(); return ret; } bool _queryRange(int left, int right) { int leftIndex = searchRanges(left); int rightIndex = searchRanges(right-1); if(leftIndex &gt;= len || rightIndex &gt;= len) return false; return leftIndex == rightIndex &amp;&amp; inRange(left, leftIndex) &amp;&amp; inRange(right-1, rightIndex); } void removeRange(int left, int right) { // if(debug) { // ops++; // cout &lt;&lt; &quot;[&quot; &lt;&lt; ops &lt;&lt; &quot;], &quot; &lt;&lt; &quot;removeRange&quot; &lt;&lt; &quot;[&quot; &lt;&lt; left &lt;&lt; &quot;, &quot; &lt;&lt; right &lt;&lt; &quot;]&quot; &lt;&lt; &quot;
&quot;; // } _removeRange(left, right); // if(debug) printRanges(); } void _removeRange(int left, int right) { int leftIndex = searchRanges(left); int rightIndex = searchRanges(right-1); // if(debug) cout &lt;&lt; &quot;leftIndex = &quot; &lt;&lt; leftIndex &lt;&lt; &quot;, rightIndex = &quot; &lt;&lt; rightIndex &lt;&lt; &quot;
&quot;; if(leftIndex == rightIndex &amp;&amp; leftIndex == len) { return; } else { int leftLeft = left, rightRight = right; if(inRange(left, leftIndex)) { leftLeft = ranges[leftIndex].first; } if(rightIndex &lt; len) { if(inRange(right-1, rightIndex)) { rightRight = ranges[rightIndex].second; rightIndex++; } } // if(debug) cout &lt;&lt; &quot;leftIndex = &quot; &lt;&lt; leftIndex &lt;&lt; &quot;, rightIndex = &quot; &lt;&lt; rightIndex &lt;&lt; &quot;
&quot;; // if(debug) cout &lt;&lt; &quot;leftLeft = &quot; &lt;&lt; leftLeft &lt;&lt; &quot;, rightRight = &quot; &lt;&lt; rightRight &lt;&lt; &quot;
&quot;; ranges.erase(ranges.begin() + leftIndex, ranges.begin() + rightIndex); len -= rightIndex - leftIndex; // if(debug) cout &lt;&lt; &quot;len = &quot; &lt;&lt; len &lt;&lt; &quot;
&quot;; if(rightRight &gt; right) { len++; ranges.insert(ranges.begin() + leftIndex, make_pair(right, rightRight)); // if(debug) cout &lt;&lt; &quot;add right len = &quot; &lt;&lt; len &lt;&lt; &quot;
&quot;; } if(leftLeft &lt; left) { len++; ranges.insert(ranges.begin() + leftIndex, make_pair(leftLeft, left)); // if(debug) cout &lt;&lt; &quot;add left len = &quot; &lt;&lt; len &lt;&lt; &quot;
&quot;; } } }};/** * Your RangeModule object will be instantiated and called as such: * RangeModule* obj = new RangeModule(); * obj-&gt;addRange(left,right); * bool param_2 = obj-&gt;queryRange(left,right); * obj-&gt;removeRange(left,right); */ 优化一些情况可以利用原有的ranges，而无需删除  RangeModule { vector&lt;pair&lt;int, int&gt;&gt; ranges; int len = 0; int ops = 0; static constexpr bool debug = false; void printRanges() { int size = ranges.size(); cout &lt;&lt; &quot;len = &quot; &lt;&lt; len &lt;&lt; &quot;, size = &quot; &lt;&lt; size &lt;&lt; &quot;
&quot;; for(int i = 0; i &lt; size; i++) { cout &lt;&lt; &quot;[&quot; &lt;&lt; ranges[i].first &lt;&lt; &quot;, &quot; &lt;&lt; ranges[i].second &lt;&lt; &quot;]
&quot;; } } bool inRange(int n, int index) { return ranges[index].first &lt;= n &amp;&amp; n &lt; ranges[index].second; } bool bigger(int n, int index) { return n &gt;= ranges[index].second; } bool smaller(int n, int index) { return ranges[index].first &gt; n; } int searchRanges(int n) { int l = 0, r = len; while(l &lt; r) { int mid = (r - l) / 2 + l; if(inRange(n, mid)) return mid; else if(bigger(n, mid)) { l = mid + 1; } else { r = mid; } } return l; }public: RangeModule() { } void addRange(int left, int right) { if(debug) { ops++; cout &lt;&lt; &quot;[&quot; &lt;&lt; ops &lt;&lt; &quot;], &quot; &lt;&lt; &quot;addRange&quot; &lt;&lt; &quot;[&quot; &lt;&lt; left &lt;&lt; &quot;, &quot; &lt;&lt; right &lt;&lt; &quot;]&quot; &lt;&lt; &quot;
&quot;; } _addRange(left, right); if(debug) printRanges(); } void _addRange(int left, int right) { int leftIndex = searchRanges(left-1); int rightIndex = searchRanges(right); // add时考虑合并相邻的集合，所以把边界放宽 if(debug) cout &lt;&lt; &quot;leftIndex = &quot; &lt;&lt; leftIndex &lt;&lt; &quot;, rightIndex = &quot; &lt;&lt; rightIndex &lt;&lt; &quot;
&quot;; if(leftIndex == rightIndex &amp;&amp; leftIndex == len) { ranges.insert(ranges.begin() + leftIndex, make_pair(left, right)); len++; } else { left = min(left, ranges[leftIndex].first); if(rightIndex &lt; len) { if(inRange(right, rightIndex)) { right = max(right, ranges[rightIndex].second); rightIndex++; } } if(leftIndex == rightIndex &amp;&amp; !inRange(left-1, leftIndex) &amp;&amp; !inRange(right, rightIndex)) { ranges.insert(ranges.begin() + leftIndex, make_pair(left, right)); len++; } else { ranges[leftIndex].first = left; ranges[leftIndex].second = right; leftIndex++; if(rightIndex &gt; leftIndex) ranges.erase(ranges.begin() + leftIndex, ranges.begin() + rightIndex); if(rightIndex &gt; leftIndex) len -= rightIndex - leftIndex; } } } bool queryRange(int left, int right) { if(debug) { ops++; cout &lt;&lt; &quot;[&quot; &lt;&lt; ops &lt;&lt; &quot;], &quot; &lt;&lt; &quot;queryRange&quot; &lt;&lt; &quot;[&quot; &lt;&lt; left &lt;&lt; &quot;, &quot; &lt;&lt; right &lt;&lt; &quot;]&quot; &lt;&lt; &quot;
&quot;; } bool ret = _queryRange(left, right); if(debug) cout &lt;&lt; (ret ? &quot;ok&quot; : &quot;not found&quot;) &lt;&lt; &quot;
&quot;; if(debug) printRanges(); return ret; } bool _queryRange(int left, int right) { int leftIndex = searchRanges(left); int rightIndex = searchRanges(right-1); if(leftIndex &gt;= len || rightIndex &gt;= len) return false; return leftIndex == rightIndex &amp;&amp; inRange(left, leftIndex) &amp;&amp; inRange(right-1, rightIndex); } void removeRange(int left, int right) { if(debug) { ops++; cout &lt;&lt; &quot;[&quot; &lt;&lt; ops &lt;&lt; &quot;], &quot; &lt;&lt; &quot;removeRange&quot; &lt;&lt; &quot;[&quot; &lt;&lt; left &lt;&lt; &quot;, &quot; &lt;&lt; right &lt;&lt; &quot;]&quot; &lt;&lt; &quot;
&quot;; } _removeRange(left, right); if(debug) printRanges(); } void _removeRange(int left, int right) { int leftIndex = searchRanges(left); int rightIndex = searchRanges(right-1); if(debug) cout &lt;&lt; &quot;leftIndex = &quot; &lt;&lt; leftIndex &lt;&lt; &quot;, rightIndex = &quot; &lt;&lt; rightIndex &lt;&lt; &quot;
&quot;; if(leftIndex == rightIndex &amp;&amp; leftIndex == len) { return; } else { int leftLeft = left, rightRight = right; if(inRange(left, leftIndex)) { leftLeft = ranges[leftIndex].first; } if(rightIndex &lt; len) { if(inRange(right-1, rightIndex)) { rightRight = ranges[rightIndex].second; rightIndex++; } } if(debug) cout &lt;&lt; &quot;leftIndex = &quot; &lt;&lt; leftIndex &lt;&lt; &quot;, rightIndex = &quot; &lt;&lt; rightIndex &lt;&lt; &quot;
&quot;; if(debug) cout &lt;&lt; &quot;leftLeft = &quot; &lt;&lt; leftLeft &lt;&lt; &quot;, rightRight = &quot; &lt;&lt; rightRight &lt;&lt; &quot;
&quot;; if(rightRight &gt; right) { rightIndex--; ranges[rightIndex].first = right; ranges[rightIndex].second = rightRight; if(debug) cout &lt;&lt; &quot;add right len = &quot; &lt;&lt; len &lt;&lt; &quot;
&quot;; } if(leftLeft &lt; left) { if(leftIndex == rightIndex) { ranges.insert(ranges.begin() + leftIndex, make_pair(leftLeft, left)); len++; } else { ranges[leftIndex].first = leftLeft; ranges[leftIndex].second = left; leftIndex++; } if(debug) cout &lt;&lt; &quot;add left len = &quot; &lt;&lt; len &lt;&lt; &quot;
&quot;; } ranges.erase(ranges.begin() + leftIndex, ranges.begin() + rightIndex); len -= rightIndex - leftIndex; if(debug) cout &lt;&lt; &quot;len = &quot; &lt;&lt; len &lt;&lt; &quot;
&quot;; } }};/** * Your RangeModule object will be instantiated and called as such: * RangeModule* obj = new RangeModule(); * obj-&gt;addRange(left,right); * bool param_2 = obj-&gt;queryRange(left,right); * obj-&gt;removeRange(left,right); */ 1334. 阈值距离内邻居最少的城市Floyd1234567891011121314151617181920212223242526272829303132333435class Solution {public: int findTheCity(int n, vector&lt;vector&lt;int&gt;&gt;&amp; edges, int distanceThreshold) { vector&lt;vector&lt;int&gt;&gt; g(n, vector&lt;int&gt;(n, INT_MAX)); vector&lt;int&gt; cnt(n, 0); for(vector&lt;int&gt;&amp; edge : edges) { g[edge[0]][edge[1]] = edge[2]; g[edge[1]][edge[0]] = edge[2]; } for(int w = 0; w &lt; n; w++) { for(int i = 0; i &lt; n; i++) { for(int j = 0; j &lt; n; j++) { if(g[i][w] != INT_MAX &amp;&amp; g[w][j] != INT_MAX &amp;&amp; g[i][w] + g[w][j] &lt; g[i][j]) g[i][j] = g[i][w] + g[w][j]; } } } for(int i = 0; i &lt; n; i++) { for(int j = 0; j &lt; n; j++) { if(i != j &amp;&amp; g[i][j] &lt;= distanceThreshold) { cnt[i]++; } } } int ret = 0; int min_num = INT_MAX; for(int i = n-1; i &gt;= 0; i--) { if(cnt[i] &lt; min_num) { min_num = cnt[i]; ret = i; } } return ret; }}; 中间节点w要放在最外层循环 优化一下下1234567891011121314151617181920212223242526272829303132333435class Solution {public: int findTheCity(int n, vector&lt;vector&lt;int&gt;&gt;&amp; edges, int distanceThreshold) { vector&lt;vector&lt;int&gt;&gt; g(n, vector&lt;int&gt;(n, INT_MAX / 2)); for(vector&lt;int&gt;&amp; edge : edges) { g[edge[0]][edge[1]] = edge[2]; g[edge[1]][edge[0]] = edge[2]; } for(int w = 0; w &lt; n; w++) { g[w][w] = 0; for(int i = 0; i &lt; n; i++) { for(int j = 0; j &lt; n; j++) { if(g[i][w] + g[w][j] &lt; g[i][j]) g[i][j] = g[i][w] + g[w][j]; } } } int ret = 0; int min_num = INT_MAX; for(int i = n-1; i &gt;= 0; i--) { int cnt = 0; for(int j = 0; j &lt; n; j++) { if(g[i][j] &lt;= distanceThreshold) { cnt++; } } if(cnt &lt; min_num) { // cout &lt;&lt; &quot;i = &quot; &lt;&lt; i &lt;&lt; &quot;, cnt[i] = &quot; &lt;&lt; cnt[i] &lt;&lt; &quot;
&quot;; min_num = cnt; ret = i; } } return ret; }}; BFS写了半天，发现带权图不能bfs求最短路径 dijkstra1234567891011121314151617181920212223242526272829303132333435363738394041424344class Solution { int min_index(int len, const vector&lt;int&gt;&amp; v, const vector&lt;bool&gt;&amp; visited) { pair&lt;int, int&gt; ret(INT_MAX, -1); for(int i = 0; i &lt; len; i++) { if(!visited[i] &amp;&amp; v[i] &lt; ret.first) { ret = {v[i], i}; } } return ret.second; }public: int findTheCity(int n, vector&lt;vector&lt;int&gt;&gt; &amp;edges, int distanceThreshold) { vector&lt;vector&lt;pair&lt;int, int&gt;&gt;&gt; g(n); for(auto&amp; edge : edges) { g[edge[0]].push_back(make_pair(edge[1], edge[2])); g[edge[1]].push_back(make_pair(edge[0], edge[2])); } int ret = -1; int min_cnt = INT_MAX; for(int node = 0; node &lt; n; node++) { int cnt = 0; vector&lt;int&gt; min_dis(n, INT_MAX &gt;&gt; 2); vector&lt;bool&gt; visited(n, false); min_dis[node] = 0; int next = node; do { visited[next] = true; for(auto&amp; [child, weight] : g[next]) { min_dis[child] = min(min_dis[child], min_dis[next] + weight); } } while((next = min_index(n, min_dis, visited)) != -1); for(int i = 0; i &lt; n; i++) { if(min_dis[i] &lt;= distanceThreshold) { cnt++; } } if(cnt &lt;= min_cnt) { min_cnt = cnt; ret = node; } } return ret; }}; 307. 区域和检索 - 数组可修改分块思路把数组分成sqrt(n)份，存储每份的和更新时，找到对应区间把值更新，O(1)求值时，把left到right对应区间的和加起来，加上right右边的不足一个区间的，减去左侧超过一个区间的，三个运算都在sqrt(n)内完成, O(sqrt(n)) 代码1234567891011121314151617181920212223242526272829303132333435363738394041424344class NumArray { vector&lt;int&gt; data; vector&lt;int&gt; preSum; int size; int len;public: NumArray(vector&lt;int&gt;&amp; nums) { data = nums; len = nums.size(); if(len == 0) return; size = sqrt(len); preSum = vector&lt;int&gt;(size + 20, 0); for(int i = 0; i &lt; len; i++) { preSum[i / size] += nums[i]; } } void update(int index, int val) { int prev = data[index]; data[index] = val; preSum[index / size] += val - prev; } int sumRange(int left, int right) { int sum = 0; for(int i = left/size; i &lt; right/size; i++) { sum += preSum[i]; } for(int i = right / size * size; i &lt;= right; i++) { sum += data[i]; } for(int i = left / size * size; i &lt; left; i++) { sum -= data[i]; } return sum; }};/** * Your NumArray object will be instantiated and called as such: * NumArray* obj = new NumArray(nums); * obj-&gt;update(index,val); * int param_2 = obj-&gt;sumRange(left,right); */ 线段树 构造一棵树 根节点代表[0, n-1]的和 两个子节点分别代表[0,(n-1)/2]和[(n-1)/2+1, n-1]的和 如果区间为0，则不继续细分 更新 根据index在树中查找，同时更新所有父节点的值 查询 对于一个查询， 如果查询范围刚好等于节点代表的范围，则返回该节点的值 如果不同，则将查询一分为两个子查询，分别交给子节点处理，直到遇到子查询与子节点代表的范围相同，将所有子查询相加 1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859class NumArray {private: vector&lt;int&gt; tree; int n; int build(int node, int l, int r, const vector&lt;int&gt;&amp; nums) { if(l == r) tree[node] = nums[l]; else { int mid = (r - l) / 2 + l; tree[node] = build(2*node+1, l, mid, nums) + build(2*node+2, mid+1, r, nums); } return tree[node]; } void updateTree(int node, int index, int l, int r, int val) { if(l == r) tree[node] = val; else { int mid = (r - l) / 2 + l; if(index &lt;= mid) { updateTree(node*2+1, index, l, mid, val); } else { updateTree(node*2+2, index, mid+1, r, val); } tree[node] = tree[2*node+1] + tree[2*node+2]; } } int sumTree(int node, int left, int right, int l, int r) { if(left == l &amp;&amp; right == r) { return tree[node]; } int mid = (r - l) / 2 + l; if(left &gt; mid) { return sumTree(node*2+2, left, right, mid+1, r); } else if(right &lt;= mid) { return sumTree(node*2+1, left, right, l, mid); } else { return sumTree(node*2+1, left, mid, l, mid) + sumTree(2*node+2, mid+1, right, mid+1, r); } }public: NumArray(vector&lt;int&gt;&amp; nums) { n = nums.size(); tree = vector&lt;int&gt;(n * 4); build(0, 0, n-1, nums); } void update(int index, int val) { updateTree(0, index, 0, n-1, val); } int sumRange(int left, int right) { return sumTree(0, left, right, 0, n-1); }};/** * Your NumArray object will be instantiated and called as such: * NumArray* obj = new NumArray(nums); * obj-&gt;update(index,val); * int param_2 = obj-&gt;sumRange(left,right); */ 765. 情侣牵手思路看了下面的提示： Say there are N two-seat couches. For each couple, draw an edge from the couch of one partner to the couch of the other partner. 让我画出座位上的人到其伴侣的箭头 如果箭头在同一个沙发上，就无需交换 如果不在同一个沙发上，就让另一个人与其交换 对每个沙发执行相同的任务 代码1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950class Solution { int n; int min_swap_cnt = INT_MAX; unordered_map&lt;int, int&gt; pos;public: int minSwapsCouples(vector&lt;int&gt;&amp; row) { n = row.size(); for(int i = 0; i &lt; n; i++) { pos[row[i]] = i; } search(0, 0, row); return min_swap_cnt; } void print(const vector&lt;int&gt;&amp; nums) { cout &lt;&lt; nums[0]; for(int i = 1; i &lt; n; i++) cout &lt;&lt; &quot;, &quot; &lt;&lt; nums[i]; cout &lt;&lt; &quot;
&quot;; } bool check(const vector&lt;int&gt;&amp; nums) { for(int i = 0; i &lt; n; i+=2) { if(abs(nums[i] - nums[i+1]) != 1) return false; } return true; } void search(int s, int cnt, vector&lt;int&gt; &amp;nums) { // print(nums); if(check(nums)) { min_swap_cnt = min(min_swap_cnt, cnt); return; } if(s &gt;= n) return; int i = s; for(int i = s; i &lt; n; i++) { int target = nums[i] + ((nums[i] &amp; 1) ? -1 : 1); int j = pos[target]; if(i/2 != j/2) { int x = (i&amp;1) ? -1 : 1; pos[target] = i + x; pos[nums[i + x]] = j; swap(nums[i + x], nums[j]); search(i + 2, cnt+1, nums); // swap(nums[i + x], nums[j]); // pos[target] = j; // pos[nums[i + x]] = i + x; // search(i + 2, cnt, nums); break; } } }}; emm,一点点蒙对的，居然对了 简化代码123456789101112131415161718192021class Solution {public: int minSwapsCouples(vector&lt;int&gt;&amp; row) { int swap_cnt = 0; int n = row.size(); vector&lt;int&gt; pos(n); for(int i = 0; i &lt; n; i++) { pos[row[i]] = i; } for(int i = 0; i &lt; n; i+=2) { int target = row[i] + ((row[i] &amp; 1) ? -1 : 1); int j = pos[target]; if(i/2 != j/2) { swap(pos[target], pos[row[i + 1]]); swap(row[i + 1], row[j]); swap_cnt++; } } return swap_cnt; }};

1、实验目的通过动态优先权算法的模拟加深对进程概念进程调度过程的理解。 2、实验内容 用C语言来实现对N个进程采用动态优先权优先算法的进程调度。 每个用来标识进程的进程控制块PCB用结构来描述，包括以下字段： 进程标识数 ID。 进程优先数 PRIORITY，并规定优先数越大的进程，其优先权越高。 进程已占用的CPU时间CPUTIME。 进程还需占用的CPU时间ALLTIME。当进程运行完毕时，ALLTIME变为0。•••• 进程的阻塞时间STARTBLOCK，表示当进程再运行STARTBLOCK个时间片后，将进入阻塞状态。 进程被阻塞的时间BLOCKTIME，表示已足赛的进程再等待BLOCKTIME个时间片后，将转换成就绪状态。 进程状态START。 队列指针NEXT，用来将PCB排成队列。 优先数改变的原则： 进程在就绪队列中呆一个时间片，优先数加1。 进程每运行一个时间片，优先数减3。 假设在调度前，系统中有5个进程，它们的初始状态如下：1234567ID 0 1 2 3 4PRIORITY 9 38 30 29 0CPUTIME 0 0 0 0 0ALLTIME 3 3 6 3 4STARTBLOCK 2 -1 -1 -1 -1BLOCKTIME 3 0 0 0 0STATE READY READY READY READY READY 为了清楚的观察各进程的调度过程，程序应将每个时间片内的情况显示出来，参照的具体格式如下：1234567891011RUNNING PROG：iREADY-QUEUE：-〉id1-〉id2BLOCK-QUEUE：-〉id3-〉id4= = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = == = =ID 0 1 2 3 4PRIORITY P0 P1 P2 P3 P4CUPTIME C0 C1 C2 C3 C4ALLTIME A0 A1 A2 A3 A4STARTBLOCK T0 T1 T2 T3 T4BLOCKTIME B0 B1 B2 B3 B4STATE S0 S1 S2 S3 S4 实验代码#include&lt;queue&gt;#include&lt;iostream&gt;#include&lt;iomanip&gt; using namespace std;typedef int ID;typedef int Priority;typedef int Time;enum State { sready, sblocked, sruning, sstop};struct PCB{ ID id; Priority priority; Time cpu_time; Time all_time; Time start_block; Time block_time; State state; public: PCB( ID id0, Priority priority0, Time cpu_time0, Time all_time0, Time start_block0, Time block_time0, State state0 ): id(id0), priority(priority0), cpu_time(cpu_time0), all_time(all_time0), start_block(start_block0), block_time(block_time0), state(state0) { }};struct cmp //��д�º���{ bool operator() (PCB* a, PCB* b) { return a-&gt;priority &lt; b-&gt;priority; //�󶥶� }};typedef priority_queue&lt;PCB*, vector&lt;PCB*&gt;, cmp&gt; mqueue;const int width = 10;void show_PCB(PCB* pcb) { string state = &quot;&quot;; switch(pcb-&gt;state) { case sready: state = &quot;ready&quot;; break; case sblocked : state = &quot;blocked&quot;;break; case sruning : state = &quot;runing&quot;;break; case sstop: state = &quot;stop&quot;;break; defalut:state=&quot;unknown&quot;;break; } cout &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; pcb-&gt;id &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; pcb-&gt;priority &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; pcb-&gt;cpu_time &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; pcb-&gt;all_time &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; pcb-&gt;start_block &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; pcb-&gt;block_time &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; state &lt;&lt; &quot;|&quot; &lt;&lt; endl; }void show_queue(queue&lt;PCB*&gt; q){ cout &lt;&lt; left &lt;&lt; setw(7*width+7) &lt;&lt; setfill('-') &lt;&lt; &quot;&quot; &lt;&lt; &quot;
&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; &quot;id&quot; &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; &quot;priority&quot; &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; &quot;cpuTime&quot; &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; &quot;allTime&quot; &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; &quot;startBlock&quot; &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; &quot;blockTime&quot; &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; &quot;state&quot; &lt;&lt; &quot;|&quot; &lt;&lt; endl; while(!q.empty()) { PCB* t = q.front(); q.pop(); show_PCB(t); } cout &lt;&lt; left &lt;&lt; setw(7*width+7) &lt;&lt; setfill('-') &lt;&lt; &quot;&quot; &lt;&lt; &quot;
&quot;;}void show_queue(mqueue q){ cout &lt;&lt; left &lt;&lt; setw(7*width+7) &lt;&lt; setfill('-') &lt;&lt; &quot;&quot; &lt;&lt; &quot;
&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; &quot;id&quot; &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; &quot;priority&quot; &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; &quot;cpuTime&quot; &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; &quot;allTime&quot; &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; &quot;startBlock&quot; &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; &quot;blockTime&quot; &lt;&lt; &quot;|&quot; &lt;&lt; left &lt;&lt; setw(width) &lt;&lt; setfill(' ') &lt;&lt; &quot;state&quot; &lt;&lt; &quot;|&quot; &lt;&lt; endl; while(!q.empty()) { PCB* t = q.top(); q.pop(); show_PCB(t); } cout &lt;&lt; left &lt;&lt; setw(7*width+7) &lt;&lt; setfill('-') &lt;&lt; &quot;&quot; &lt;&lt; &quot;
&quot;;}queue&lt;PCB*&gt; finished;void run_a_time(mqueue&amp; ready,mqueue&amp; blocked,PCB* runing) { mqueue t_ready, t_blocked; runing = ready.top(); ready.pop(); runing-&gt;priority -= 3; runing-&gt;cpu_time += 1; runing-&gt;all_time -= 1; runing-&gt;start_block -= 1; if(runing-&gt;start_block == 0) { t_blocked.push(runing); runing-&gt;state = sruning; } else { if(runing-&gt;all_time &gt; 0) { t_ready.push(runing); } else { finished.push(runing); runing-&gt;state = sstop; } } mqueue t_queue = blocked; while(!t_queue.empty()) { PCB* t = t_queue.top(); t_queue.pop(); t-&gt;block_time -= 1; if(t-&gt;block_time == 0) { t_ready.push(t); t-&gt;block_time = 0; t-&gt;start_block = -1; t-&gt;state = sready; } else { t_blocked.push(t); t-&gt;state = sblocked; } } t_queue = ready; while(!t_queue.empty()) { PCB* t = t_queue.top(); t_queue.pop(); t-&gt;priority += 1; t-&gt;start_block -= 1; if(t-&gt;start_block == 0) { t_blocked.push(t); t-&gt;state = sblocked; } else { t_ready.push(t); t-&gt;state = sready; } } ready = t_ready; blocked = t_blocked; }int main() { mqueue ready, blocked; PCB* runing = nullptr; PCB* pcbs[] = { new PCB(0,9,0,3,2,3, sready), new PCB(1,38,0,3,-1,0, sready), new PCB(2,30,0,6,-1,0, sready), new PCB(3,29,0,3,-1,0, sready), new PCB(4,0,0,4,-1,0, sready) }; int pcb_num = sizeof(pcbs)/sizeof(PCB*); for(int i = 0; i &lt; pcb_num; i++) { ready.push(pcbs[i]); } show_queue(ready); int clock_ = 1; while(!ready.empty() || !blocked.empty()) { cout &lt;&lt; &quot;clock = &quot; &lt;&lt; clock_ &lt;&lt; endl; run_a_time(ready, blocked, runing); cout &lt;&lt; &quot;ready queue:&quot; &lt;&lt; endl; show_queue(ready); cout &lt;&lt; &quot;blocked queue:&quot; &lt;&lt; endl; show_queue(blocked); //system(&quot;pause&quot;); clock_++; } show_queue(finished); //delete for(int i = 0; i &lt; pcb_num; i++) { delete pcbs[i]; }}

1、实验目的通过具体的文件存储空间的管理、文件的物理结构、目录结构和文件操作的实现，加深对文件系统内部功能和实现过程的理解。 2、实验内容 在内存中开辟一个虚拟磁盘空间作为文件存储器，在上面实现一个简单单用户文件系统。退出时应该将该虚拟文件系统保存到磁盘上，以便下次可以再将它恢复到内存对虚拟磁盘空间中。 文件存储空间对分配可以采用显式链接分配或者其他的办法。 空闲空间的管理可以选择位示图或者其他的办法。如果采用位示图来管理文件存储空间，并采用显式链接分配方式，那么可以将位示图合并到FAT中。 文件目录结构采用多级目录结构。为了简单起见，可以不使用索引结点，其中的每个目录项应包含文件名、物理地址、长度等信息，还可以通过目录项实现对文件对读和写的保护。 要求提供以下有关的操作：1234567891011√format：对文件存储器进行格式化，即按照文件系统对结构对虚拟磁盘空间进行布局，并在其上创建根目录以及用于管理文件存储空间等的数据结构。√mkdir：用于创建子目录；√rmdir：用于删除目录；√ls：用于显示目录；√cd：用于更改当前目录；√create：用于创建文件；√open：用于打开文件；√close：用于关闭文件；√write：用于写文件；√read：用于读文件√rm：用于删除文件。 代码#include &lt;iostream&gt;#include &lt;vector&gt;#include &lt;iomanip&gt;#include &lt;fstream&gt;using std::string;using std::vector;using std::cout;using std::endl;using std::cin;using std::ifstream;using std::ofstream;using std::ios;class FCB{public: int first_block; string fileName; int size; int real_size; FCB(int first_block0,const string &amp;fileName0, int size0, int real_size0): first_block(first_block0), fileName(fileName0), size(size0), real_size(real_size0*4) { }}; //文件控制块class DirItem { //文件树 string name; vector&lt;FCB*&gt; files; //目录下的文件 vector&lt;DirItem*&gt; dirs; //目录下的文件夹，树节点public: DirItem(const string&amp; name0):name(name0) {} void addFile(int first_block, const string&amp; fileName,int size, int real_size) { for (auto i = files.begin(); i != files.end(); i++) { if ((*i)-&gt;fileName == fileName) { cout &lt;&lt; &quot;same file name&quot; &lt;&lt; endl; return; } } files.push_back(new FCB(first_block, fileName, size, real_size)); } void addDir(DirItem* dir) { dirs.push_back(dir); } vector&lt;DirItem*&gt; getDirs() { return dirs; } vector&lt;FCB*&gt; getFiles() { return files; } string getName() { return name; } void del_file(const string&amp; fileName) { for (auto i = files.begin(); i != files.end(); i++) { if ((*i)-&gt;fileName == fileName) { files.erase(i); break; } } } void del_dir(const string&amp; fileName) { for (auto i = dirs.begin(); i != dirs.end(); i++) { if ((*i)-&gt;getName() == fileName) { dirs.erase(i); break; } } } void clear() { for (DirItem* item : dirs) { delete item; } for (FCB* item : files) { delete item; } dirs.clear(); files.clear(); } //递归删除时用到，删除当前目录下的目录和文件的指针};class diskMgr { //磁盘 vector&lt;int&gt; blocks; //fat表 int n = 16; int block_num = n*n; int block_size = 4; //每块4B int disk_capacity = block_num * block_size; //1M vector&lt;vector&lt;int&gt;&gt; bit_map; //0空，1有，位视图public: vector&lt;char&gt; disk; diskMgr() { disk = vector&lt;char&gt;(disk_capacity, '\0'); blocks = vector&lt;int&gt;(block_num, -1); bit_map = vector&lt;vector&lt;int&gt;&gt;(n, vector&lt;int&gt;(n, 0)); } int getSize(int blockNum) { int n = 0; while (blockNum != -1) { n++; blockNum = blocks[blockNum]; } return n; } //当前块号开始的文件一个有多少块儿 int find_empty_block() { for (int i = 0; i &lt; n; i++) { for (int j = 0; j &lt; n; j++) { if (bit_map[i][j] == 0) { return n*i+j; } } } return -1; }//找到一个空闲盘块，从位视图 void update_bit_map(int x, int notempty) { int i = x / n,j = x % n; bit_map[i][j] = notempty; }//更新位视图 void del(int blockNum) { while (blockNum != -1) { for(int i = 0; i &lt; block_size; i++) { disk[blockNum * block_size + i] = '\0'; } update_bit_map(blockNum, 0); int t = blocks[blockNum]; blocks[blockNum] = -1; blockNum = t; } } //删除文件 vector&lt;char&gt; read(int blockNum) { vector&lt;char&gt; data; while (blockNum != -1) { for(int i = 0; i &lt; block_size; i++) { data.push_back(disk[blockNum * block_size + i]); } blockNum = blocks[blockNum]; } return data; } //读取文件 int write(vector&lt;char&gt; data) { int first_block = find_empty_block(); //找到初始位置 if (first_block == -1) return -1; int len = int(data.size()); int blockn = len%block_size == 0 ? len/block_size : len/block_size+1; //一共需要的盘块儿数 int next_block = first_block; int temp = next_block; int fix = (block_size - len % block_size) % block_size; for (int i = 0; i &lt; fix; ++i) { //数据长度对齐 data.push_back('*'); } for (int i = 0; i &lt; blockn; i++) { //存数据 if (temp == -1) { break; } next_block = temp; for (int j = 0; j &lt; block_size; j++) { disk[next_block*block_size+j] = data[i*block_size+j]; } update_bit_map(next_block, 1); temp = find_empty_block(); blocks[next_block] = temp; } blocks[next_block] = -1; return first_block; }};#define chart_head std::left &lt;&lt; std::setw(len+1) &lt;&lt; std::setfill('-') &lt;&lt; &quot;&quot;#define chart_cell &quot;|&quot; &lt;&lt; std::left &lt;&lt; std::setw(len) &lt;&lt; std::setfill(' ')class fileMgr { DirItem * root; //根节点 diskMgr dm;//磁盘管理器 DirItem * cur; //当前命令行执的工作目录 string cur_path; //工作命令 DirItem* addmdir(DirItem * node, string name) { DirItem* newNode = new DirItem(name); node-&gt;addDir(newNode); return newNode; }public: fileMgr() { root = new DirItem(&quot;/&quot;); DirItem * temp = addmdir(addmdir(root, &quot;apps&quot;), &quot;tencent&quot;); addmdir(temp, &quot;qq&quot;); addmdir(temp, &quot;qqgame&quot;); addmdir(temp, &quot;qqmusic&quot;); temp = addmdir(root, &quot;docs&quot;); addmdir(temp, &quot;words&quot;); addmdir(temp, &quot;ppts&quot;); addmdir(temp, &quot;excels&quot;); root-&gt;addDir(new DirItem(&quot;pics&quot;)); root-&gt;addDir(new DirItem(&quot;musics&quot;)); cur = root; cur_path = &quot;/&quot;; cout_hint(); } //初始化一些文件夹 void ls() { int len = 20; cout &lt;&lt; chart_head &lt;&lt; chart_head &lt;&lt; chart_head &lt;&lt; chart_head &lt;&lt; endl &lt;&lt; chart_cell &lt;&lt; &quot;file/dir name&quot; &lt;&lt; chart_cell &lt;&lt; &quot;type&quot; &lt;&lt; chart_cell &lt;&lt; &quot;size&quot; &lt;&lt; chart_cell &lt;&lt; &quot;real size&quot; &lt;&lt; &quot;|&quot; &lt;&lt; std::endl &lt;&lt; chart_head &lt;&lt; chart_head &lt;&lt; chart_head &lt;&lt; chart_head &lt;&lt; endl; vector&lt;DirItem*&gt; dirs = cur-&gt;getDirs(); for (auto i = dirs.begin(); i != dirs.end(); i++) { cout &lt;&lt; chart_cell &lt;&lt; (*i)-&gt;getName() &lt;&lt; chart_cell &lt;&lt; &quot;directory&quot; &lt;&lt; chart_cell &lt;&lt; &quot;--&quot; &lt;&lt; chart_cell &lt;&lt; &quot;--&quot; &lt;&lt; &quot;|&quot; &lt;&lt; std::endl; } vector