; if(mask &amp; flag) logger(LOG_INFO, &quot;%d&quot;, 0); for(int cnt = 1; cnt &lt; 32; cnt++) { mask &lt;&lt;= 1; if(mask &amp; flag) logger(LOG_INFO, &quot;%d&quot;, cnt); }}#define printINT(info, x) logger(LOG_INFO, &quot;(&quot;#info&quot;).&quot;#x&quot;: %d&quot;, (info).x)#define printUINT(info, x) logger(LOG_INFO, &quot;(&quot;#info&quot;).&quot;#x&quot;: %ld&quot;, (info).x)#define printTIME(ds, x) logger(LOG_INFO, &quot;(&quot;#ds&quot;).&quot;#x&quot;: %s&quot;, ctime(&amp;(ds).x))int printInfo(int id) { union semun arg; struct seminfo info; struct semid_ds ds; arg.__buf = &amp;info; CHECK(semctl(id, 0, SEM_INFO, arg) != -1, STRING_MSG); printINT(info, semmap); printINT(info, semmni); printINT(info, semmns); printINT(info, semmnu); printINT(info, semmsl); printINT(info, semopm); printINT(info, semume); printINT(info, semusz); printINT(info, semvmx); printINT(info, semaem); arg.buf = &amp;ds; CHECK(semctl(id, 0, IPC_STAT, arg) != -1, STRING_MSG); printUINT(ds, sem_nsems); printTIME(ds, sem_otime); printTIME(ds, sem_ctime); return 0;}int wrapPrintFlag(int flag, int (*func)(EventFlag_t *, int)) { int currentFlag = 0; CHECK_LOG(getEventFlag(eventFlag, &amp;currentFlag) != -1, STRING_MSG); printFlag(currentFlag); CHECK_LOG((*func)(eventFlag, flag) != -1, STRING_MSG); CHECK_LOG(getEventFlag(eventFlag, &amp;currentFlag) != -1, STRING_MSG); printFlag(currentFlag); return 0;}#define FLAG_RANGE(flg) ((16 &lt;= (flg) &amp;&amp; (flg) &lt; 31) || (0 &lt;= (flg) &amp;&amp; (flg) &lt; 15))#define XXSTRING(s) XSTRING(s) //与层数相关#define XSTRING(s) STRING(s)#define STRING(s) #sint main(int argc, char **argv) { CHECK_EXIT(argc &gt; 1, &quot;Usage: %s destroy|waitAny|waitAll|add|clear|get [flag]&quot;, argv[0]); eventFlag = newEventFlag(argv[0], 'x'); CHECK_EXIT(eventFlag != NULL, STRING_MSG); int flag = 0; for(int i = 2; i &lt; argc; i++) { int flg = safe_atoi(argv[i]); if(!FLAG_RANGE(flg)){ CHECK_LOG(false, &quot;Usage: %s&quot;, XXSTRING(FLAG_RANGE(flg))); continue; } flag |= (1 &lt;&lt; flg); } printInfo(eventFlag-&gt;semid); logger(LOG_INFO, &quot;start %s&quot;, argv[1]); if(!strcmp(argv[1], &quot;waitAny&quot;)) { CHECK_LOG(wrapPrintFlag(flag, waitForAny) != -1, STRING_MSG); } else if(!strcmp(argv[1], &quot;waitAll&quot;)) { CHECK_LOG(wrapPrintFlag(flag, waitForAll) != -1, STRING_MSG); } else if(!strcmp(argv[1], &quot;add&quot;)) { CHECK_LOG(wrapPrintFlag(flag, setEventFlag) != -1, STRING_MSG); } else if(!strcmp(argv[1], &quot;clear&quot;)) { CHECK_LOG(wrapPrintFlag(flag, clearEventFlag) != -1, STRING_MSG); } else if(!strcmp(argv[1], &quot;get&quot;)) { CHECK_LOG(getEventFlag(eventFlag, &amp;flag) != -1, STRING_MSG); printFlag(flag); } else if(!strcmp(argv[1], &quot;destroy&quot;)) { destroyEventFlag(&amp;eventFlag); } else { CHECK_EXIT(false, &quot;Usage: %s waitAny|waitAll|add|clear|get [flag]&quot;, argv[0]); } logger(LOG_INFO, &quot;end %s&quot;, argv[1]);}
